-- Run after the original five scripts. Adds login storage; passwords are
-- salted scrypt hashes generated by scripts/setup.mjs, never plaintext SQL.
USE exoplanet_db;
CREATE TABLE IF NOT EXISTS app_account (
 researcher_id INT PRIMARY KEY,
 password_hash VARCHAR(256) NOT NULL,
 enabled BOOLEAN NOT NULL DEFAULT TRUE,
 FOREIGN KEY(researcher_id) REFERENCES researcher(researcher_id) ON DELETE CASCADE
) ENGINE=InnoDB;
DELIMITER $$
CREATE TRIGGER trg_planet_host_update BEFORE UPDATE ON planet FOR EACH ROW
BEGIN
 IF NEW.star_id <> OLD.star_id AND EXISTS(SELECT 1 FROM discovery WHERE planet_id=OLD.planet_id) THEN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Cannot change host of a planet with discovery records';
 END IF;
END$$
CREATE TRIGGER trg_mission_history_update BEFORE UPDATE ON mission FOR EACH ROW
BEGIN
 IF EXISTS(SELECT 1 FROM discovery WHERE mission_id=OLD.mission_id
 AND (discovery_date < NEW.launch_date OR NEW.status='PLANNED')) THEN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Mission update would invalidate discovery history';
 END IF;
END$$
CREATE TRIGGER trg_observation_delete BEFORE DELETE ON mission_star FOR EACH ROW
BEGIN
 IF EXISTS(SELECT 1 FROM discovery d JOIN planet p USING(planet_id)
 WHERE d.mission_id=OLD.mission_id AND p.star_id=OLD.star_id) THEN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Observation is referenced by discovery history';
 END IF;
END$$
CREATE TRIGGER trg_observation_update BEFORE UPDATE ON mission_star FOR EACH ROW
BEGIN
 IF (NEW.mission_id<>OLD.mission_id OR NEW.star_id<>OLD.star_id)
 AND EXISTS(SELECT 1 FROM discovery d JOIN planet p USING(planet_id)
 WHERE d.mission_id=OLD.mission_id AND p.star_id=OLD.star_id) THEN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Observation is referenced by discovery history';
 END IF;
END$$
DELIMITER ;
